/**
 *
 * Menu is a navigation component that displays a list of items, with support for items, checkbox items, radio items, submenus, and inline rendering.
 *
 * [Live Demo](https://www.primereact.org/menu/)
 *
 * @module MenuRoot
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseMenuExposes, UseMenuItemSelectEvent, UseMenuOpenChangeEvent, UseMenuProps, UseMenuState } from '@primereact/types/headless/menu';
import type { BaseComponentProps, PassThroughType } from '../..';
/**
 * Defines passthrough(pt) options type in Menu component.
 */
export type MenuRootPassThroughType<E> = PassThroughType<MenuRootInstance, E>;
/**
 * Defines passthrough(pt) options of Menu component.
 */
export interface MenuRootPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: MenuRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the list's DOM element.
     */
    list?: MenuRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the item's DOM element.
     */
    item?: MenuRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the label's DOM element.
     */
    label?: MenuRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the submenu's DOM element.
     */
    sub?: MenuRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the trigger's DOM element.
     */
    trigger?: MenuRootPassThroughType<React.HTMLAttributes<HTMLButtonElement>>;
    /**
     * Used to pass attributes to the subtrigger's DOM element.
     */
    subtrigger?: MenuRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the checkbox item indicator's DOM element.
     */
    checkboxItemIndicator?: MenuRootPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
    /**
     * Used to pass attributes to the radio item indicator's DOM element.
     */
    radioItemIndicator?: MenuRootPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
    /**
     * Used to pass attributes to the submenu indicator's DOM element.
     */
    submenuIndicator?: MenuRootPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
    /**
     * Used to pass attributes to the separator's DOM element.
     */
    separator?: MenuRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the popup's DOM element.
     */
    popup?: MenuRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the arrow's DOM element.
     */
    arrow?: MenuRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the positioner's DOM element.
     */
    positioner?: MenuRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the subpositioner's DOM element.
     */
    subpositioner?: MenuRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the subpopup's DOM element.
     */
    subpopup?: MenuRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the subportal's DOM element.
     */
    subportal?: MenuRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Event fired when the menu's open state changes.
 * @extends UseMenuOpenChangeEvent
 */
export interface MenuRootOpenChangeEvent extends UseMenuOpenChangeEvent {
}
/**
 * Event fired when an item inside the menu is selected. Aliased from the
 * headless event so consumers don't need to import it from a separate path.
 */
export interface MenuItemSelectEvent extends UseMenuItemSelectEvent {
}
/**
 * Defines valid properties in Menu component.
 */
export interface MenuRootProps extends BaseComponentProps<MenuRootInstance, Omit<UseMenuProps, 'onOpenChange'>, MenuRootPassThrough> {
    /**
     * Whether the menu should close when an item is activated. Item-level
     * `closeOnSelect` always overrides this default.
     * @default true
     */
    closeOnSelect?: boolean | undefined;
    /**
     * Callback fired when any item inside the menu is activated (clicked or
     * triggered with keyboard). Calling `event.preventDefault()` keeps the
     * menu open regardless of `closeOnSelect`.
     */
    onSelect?: (event: MenuItemSelectEvent) => void;
    /**
     * Callback fired when the menu's open state changes.
     * @param event.value The new value of the menu's open state.
     * @returns void
     */
    onOpenChange?: (event: MenuRootOpenChangeEvent) => void;
}
/**
 * Defines valid state in Menu component.
 * @extends UseMenuState
 */
export interface MenuRootState extends UseMenuState {
}
/**
 * Defines the methods and properties exposed by Menu component.
 * @extends UseMenuExposes
 */
export interface MenuRootExposes extends UseMenuExposes {
}
/**
 * Instance of Menu component.
 */
export type MenuRootInstance = ComponentInstance<MenuRootProps, MenuRootState, MenuRootExposes>;
